#include <iostream>
#include <vector>
using namespace std;

int binarySearch(vector<int>& nums, int target, bool leftmost) {
  // 左索引的初始值为 0
  int left = 0;
  // 右索引的初始值是数组中元素的数量
  int right = nums.size();
  // left + 1 >= right 将完成 while 循环
  while (left + 1 < right) {
    int mid = (right + left) / 2;

    if (nums[mid] == target) {
      if (leftmost) {
        right = mid;
      } else {
        left = mid;
      }
    } else if (nums[mid] < target) {
      // 在数组的左半部分搜索是没有意义的
      left = mid;
    } else {
      // 在数组的右半部分搜索没有意义
      right = mid;
    }
  }
  // left 可以是答案的索引
  if (nums[left] == target) {
    return left;
  }
  // right 可能是寻找的索引
  if (right < nums.size() && nums[right] == target) {
    return right;
  }
  // 数组中没有目标
  return -1;
}

int findCount(vector<int>& nums, int target) {
  int left = binarySearch(nums, target, true);

  if (left < 0) {
    return -1;
  }

  int right = binarySearch(nums, target, false);

  return right - left + 1;
}

int main() {
  vector<int> nums = {1, 5, 5, 5, 11, 11, 15, 19, 19};

  cout << "The number of occurrences of 5 is ---> "  << findCount(nums, 5) << endl;
  cout << "The number of occurrences of 20 is ---> "  << findCount(nums, 20) << endl;
  cout << "The number of occurrences of 1 is ---> "  << findCount(nums, 1) << endl;
  cout << "The number of occurrences of 19 is ---> "  << findCount(nums, 19) << endl;

  return 0;
}

